import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.BU31gs4v.js";const _=JSON.parse('{"title":"附录 B 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/b-glossary.md","filePath":"appendix/b-glossary.md","lastUpdated":1791479463000}'),a={name:"appendix/b-glossary.md"};function c(s,t,n,i,m,l){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="附录-b-术语表" tabindex="-1">附录 B 术语表 <a class="header-anchor" href="#附录-b-术语表" aria-label="Permalink to &quot;附录 B 术语表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>含义</th><th>章节</th></tr></thead><tbody><tr><td>agent</td><td>一个有身份（id）、有记忆的长期存在的智能体；对话是它和外界的一次次交互</td><td>1</td></tr><tr><td>harness</td><td>包在模型外面的程序：拼上下文、执行工具、存储与整理记忆。letta-code 就是一个 harness</td><td>0</td></tr><tr><td>回合（turn）</td><td>用户发一条消息，到 agent 给出不带工具调用的回复为止</td><td>Lab 1</td></tr><tr><td>步（step）</td><td>回合中的一次模型调用。反思的 step-count 触发器数的是 assistant 步</td><td>14</td></tr><tr><td>core memory（核心记忆）</td><td>常驻系统提示的记忆；v2 中即根目录下的 Markdown 文件</td><td>1、5</td></tr><tr><td>memory block（记忆块）</td><td>MemGPT/Letta 服务器中的核心记忆单元：label、value、description、limit、read_only</td><td>4</td></tr><tr><td>MemFS</td><td>记忆文件系统：一个 git 仓库，里面是 Markdown 记忆文件、技能与其他文件</td><td>2</td></tr><tr><td>v1 / v2 布局</td><td>v1：core 在 <code>system/</code>；v2：core 在根目录，根目录有 <code>MEMORY.md</code></td><td>2、5</td></tr><tr><td><code>MEMORY.md</code></td><td>无 frontmatter 的索引文件；根索引进入系统提示，子目录索引使该目录成为记忆</td><td>5</td></tr><tr><td>deferred memory（延迟/按需记忆）</td><td>带索引的子目录里的文件；系统提示中只有目录条目</td><td>5、8</td></tr><tr><td>投影（projection）</td><td>记忆在文件系统上的表示；<code>isProjectedMemoryPath</code> 判断文件是否属于记忆</td><td>5</td></tr><tr><td>skill（技能）</td><td><code>skills/&lt;name&gt;/SKILL.md</code>，程序性记忆，按需加载</td><td>5</td></tr><tr><td>recall memory</td><td>全部历史消息；只追加，可检索，不可修改</td><td>1、13</td></tr><tr><td>frontmatter</td><td>文件开头 <code>---</code> 包围的元数据；v2 要求恰好 <code>name</code> 和 <code>description</code></td><td>7</td></tr><tr><td>pre-commit hook</td><td>git 提交前运行的脚本；记忆仓库用它校验格式和预算</td><td>7</td></tr><tr><td><code>.memfs.config.json</code></td><td>预算与约束配置；本身受保护，修改需要人类批准</td><td>7</td></tr><tr><td>审计（audit）</td><td>用临时索引校验已提交的 HEAD，防 hook 被绕过</td><td>7</td></tr><tr><td>编译（compile）</td><td>把已提交的记忆渲染成文本并替换系统提示中的 <code>{CORE_MEMORY}</code></td><td>8</td></tr><tr><td><code>{CORE_MEMORY}</code></td><td>系统提示里记忆的插入点</td><td>8</td></tr><tr><td>memfsRevision</td><td>编译时记忆仓库 HEAD 的提交号</td><td>9</td></tr><tr><td>rawSystemHash</td><td>原始系统提示（未注入记忆）的 sha256</td><td>9</td></tr><tr><td><code>&lt;memory_update&gt;</code></td><td>对话中途记忆变化时追加给模型的新记忆全文；系统提示保持不变</td><td>3、9</td></tr><tr><td>prompt caching（提示缓存）</td><td>服务商按请求前缀缓存；系统提示一变，缓存全部失效</td><td>9</td></tr><tr><td><code>&lt;system-reminder&gt;</code></td><td>harness 发给模型的自动通知，以 user 角色消息承载</td><td>9</td></tr><tr><td>agent-info</td><td>每个对话首条消息附带的提醒：agent id、记忆目录等</td><td>9</td></tr><tr><td>地板（floor）</td><td>系统提示 + 工具定义的 token 数，每次请求都要付</td><td>11</td></tr><tr><td>compaction（压缩）</td><td>用一条摘要替换上下文开头的一段消息</td><td>12</td></tr><tr><td>sliding window（滑动窗口）</td><td>只摘要最前面一部分、保留最近消息的压缩模式</td><td>12</td></tr><tr><td><code>in_context_message_ids</code></td><td>当前在上下文窗口里的消息 id 列表</td><td>12</td></tr><tr><td>summary_message</td><td>压缩摘要消息的类型；存储上是 user 角色</td><td>12、13</td></tr><tr><td>BM25</td><td>经典的文本相关性排序公式（k1、b 两个参数）</td><td>13</td></tr><tr><td>检索回声（search echo）</td><td>历史中的检索调用、检索结果、以及正在问的问题本身；需要降权</td><td>13</td></tr><tr><td>reflection / sleeptime / dream</td><td>对话之间在后台回顾经历、整理记忆的子 agent</td><td>14、15</td></tr><tr><td>compaction-event / step-count</td><td>反思的两种自动触发器</td><td>14</td></tr><tr><td>水位线（watermark）</td><td><code>reflected_through_message_id</code>：反思到了哪条消息</td><td>14</td></tr><tr><td>payload</td><td>交给反思子 agent 的 transcript 切片文件（<code>$TRANSCRIPT_PATH</code>）</td><td>15</td></tr><tr><td>worktree</td><td>同一 git 仓库的另一个检出；反思和 worker 在其中工作</td><td>16</td></tr><tr><td>merged / no_changes / parent_dirty / merge_conflict / dirty_uncommitted / failed</td><td>反思收尾的六种状态；只有前两种消费 transcript</td><td>16</td></tr><tr><td>memory operation lease（记忆操作锁）</td><td>串行化 harness 自己的记忆写者的文件锁；持有者死亡才回收</td><td>17</td></tr><tr><td>memory worker</td><td>主 agent 委派的后台记忆更新子 agent</td><td>17</td></tr><tr><td>conflict repair</td><td>同步冲突或校验失败后启动的修复子 agent</td><td>17</td></tr><tr><td>remoteMemfs / localMemfs</td><td>后端能力：记忆仓库在服务器上 / 在本机</td><td>2、18</td></tr><tr><td>cross-agent guard</td><td>进程内文件工具的跨 agent 路径检查（字面 + realpath）</td><td>19</td></tr><tr><td>bwrap（bubblewrap）</td><td>Linux 上用挂载命名空间实现的沙箱</td><td>19</td></tr><tr><td>Seatbelt</td><td>macOS 的沙箱机制（<code>sandbox-exec</code>）</td><td>19</td></tr><tr><td>Memory Palace</td><td>记忆的只读可视化页面（<code>/palace</code>）</td><td>20</td></tr><tr><td><code>/doctor</code></td><td>用观察到的行为作证据、诊断并修复上下文的流程</td><td>20</td></tr></tbody></table>',2)])])}const g=d(a,[["render",c]]);export{_ as __pageData,g as default};
